.nav button[data-view="vehiclesystem"]:before{content:"🚗"}
#vehiclesystem .vehicle-module-head{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:14px}
#vehiclesystem .vehicle-module-head h2{margin:0;font-size:20px}
#vehiclesystem .vehicle-module-head p{margin:5px 0 0;color:var(--muted);font-size:12px}
#vehiclesystem .vehicle-module-nav{display:flex;gap:7px;flex-wrap:wrap;padding:8px;background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow-sm);margin-bottom:14px}
#vehiclesystem .vehicle-module-nav button{border:0;background:#f3f4f6;color:#374151;border-radius:10px;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer}
#vehiclesystem .vehicle-module-nav button.active{background:#17191e;color:#fff}
#vehiclesystem .vehicle-page{display:none}
#vehiclesystem .vehicle-page.active{display:block}
#vehiclesystem .titlebar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:15px;flex-wrap:wrap}
#vehiclesystem .titlebar h2{margin:0;font-size:18px}
#vehiclesystem .grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}
#vehiclesystem .grid4 .stat{min-height:105px}
#vehiclesystem .formgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
#vehiclesystem label{font-size:12px;font-weight:800;display:block;margin-bottom:6px;color:#3f4651}
#vehiclesystem input,#vehiclesystem select,#vehiclesystem textarea{width:100%;border:1px solid #dfe3e8;border-radius:11px;padding:11px 12px;background:#fff;font:inherit}
#vehiclesystem textarea{min-height:90px;resize:vertical}
#vehiclesystem .full{grid-column:1/-1}
#vehiclesystem .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
#vehiclesystem button.primary,#vehiclesystem button.secondary,#vehiclesystem button.danger,#vehiclesystem button.info{border:0;border-radius:10px;padding:10px 14px;cursor:pointer;font:inherit;font-weight:800}
#vehiclesystem button.primary{background:linear-gradient(135deg,#a77d2d,#c3a15b);color:#fff}
#vehiclesystem button.secondary{background:#17191e;color:#fff}
#vehiclesystem button.danger{background:#fdeaea;color:#ad2e2e}
#vehiclesystem button.info{background:#edf3ff;color:#245ac5}
#vehiclesystem table{width:100%;border-collapse:collapse;font-size:12px}
#vehiclesystem th,#vehiclesystem td{padding:10px;border-bottom:1px solid var(--line);text-align:right;vertical-align:top}
#vehiclesystem th{background:#f7f8fa;color:#444b56}
#vehiclesystem .toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px}
#vehiclesystem .toolbar input{max-width:360px}
#vehiclesystem .small{font-size:12px;color:var(--muted)}
#vehiclesystem .empty{padding:24px;text-align:center;color:var(--muted)}
#vehiclesystem .pill{padding:4px 8px;border-radius:999px;font-size:11px;font-weight:800;display:inline-block}
#vehiclesystem .pill.available{background:#ecfdf3;color:#137a43}
#vehiclesystem .pill.out{background:#fff4e5;color:#9a6700}
#vehiclesystem .pill.maintenance,#vehiclesystem .pill.returned{background:#eef4ff;color:#3538cd}
#vehiclesystem .pill.pending{background:#fff1f0;color:#b42318}
#vehiclesystem .checkgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
#vehiclesystem .checkitem{border:1px solid var(--line);border-radius:10px;padding:10px;background:#fafafa}
#vehiclesystem .checkitem label{font-weight:400;margin:0;display:flex;gap:8px;align-items:center}
#vehiclesystem .checkitem input{width:auto}
#vehiclesystem .diagram-wrap{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}
#vehiclesystem .diagram-card{border:1px solid var(--line);border-radius:12px;padding:12px;background:#fcfcfc}
#vehiclesystem .diagram-toolbar{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}
#vehiclesystem .svgbox{background:#fff;border:1px dashed #d1d5db;border-radius:12px;padding:10px}
#vehiclesystem .svgbox svg{width:100%;height:auto}
#vehiclesystem .mark-x line{stroke:#c81e1e;stroke-width:4;stroke-linecap:round}
#vehiclesystem .click-zone{fill:rgba(183,146,59,.06);stroke:#d7dbe1;stroke-width:1.5;stroke-dasharray:5 4}
#vehiclesystem .vehicle-line{fill:none;stroke:#56616d;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
#vehiclesystem .vehicle-fill{fill:#e8edf3;stroke:#56616d;stroke-width:2}
#vehiclesystem .legend{font-size:12px;color:var(--muted);margin-top:8px;line-height:1.7}
#vehiclesystem a.filelink{color:#2864d7;text-decoration:none;font-weight:700}
#vehiclesystem .terms-box{border:1px solid var(--line);border-radius:12px;background:#fffdf6;padding:14px;margin-top:8px}
#vehiclesystem .terms-box h4{margin:0 0 10px;font-size:15px;color:#6e5412}
#vehiclesystem .terms-list{margin:0;padding-right:22px;line-height:1.9;font-size:13px}
#vehiclesystem .terms-list li{margin-bottom:8px}
#vehiclesystem .terms-en{display:block;direction:ltr;text-align:left;color:#4b5563;margin-top:3px;font-size:12.5px;line-height:1.6}
#vehiclesystem .terms-confirm{margin-top:12px;padding:10px 12px;border:1px solid #e7d6aa;border-radius:10px;background:#fff}
#vehiclesystem .terms-confirm label{display:flex;gap:8px;align-items:flex-start;margin:0}
#vehiclesystem .terms-confirm input{width:auto;margin-top:3px}
#vehiclesystem .x-counter{font-size:12px;background:#fff5f5;color:#991b1b;border:1px solid #fecaca;padding:6px 10px;border-radius:999px}
#vehiclesystem .print-logo{display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:8px}
#vehiclesystem .print-logo img{width:70px;height:70px;object-fit:contain}
@media(max-width:1000px){#vehiclesystem .grid4{grid-template-columns:repeat(2,1fr)}#vehiclesystem .formgrid{grid-template-columns:1fr}#vehiclesystem .diagram-wrap{grid-template-columns:1fr}#vehiclesystem .checkgrid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){#vehiclesystem .grid4{grid-template-columns:1fr}#vehiclesystem .checkgrid{grid-template-columns:1fr}#vehiclesystem .vehicle-module-nav{overflow:auto;flex-wrap:nowrap}#vehiclesystem .vehicle-module-nav button{white-space:nowrap}}
@media print{#vehiclesystem .vehicle-module-head,#vehiclesystem .vehicle-module-nav{display:none!important}#vehiclesystem .vehicle-page{display:none!important}#veh_printArea{display:block!important}.top,.nav,.pro-pagebar,.site-footer{display:none!important}}


/* V7.3 — keep selected vehicle handover/return fields bilingual at all times */
.force-bilingual .terms-en,.force-bilingual .en-fixed{display:block;direction:ltr;text-align:left;color:#4b5563;margin-top:3px;font-size:12.5px;line-height:1.6}
