/* Source style block: professional-ui-v4 */

:root{
  --bg:#f5f6f8;--card:#ffffff;--text:#16191f;--muted:#6b7280;--line:#e7e9ee;
  --gold:#b89348;--gold2:#d4b46e;--gold-soft:#f7f1e3;--black:#111317;--black2:#1c2027;
  --green:#138a55;--red:#c63c45;--blue:#3367d6;--orange:#c97b22;
  --shadow-sm:0 6px 18px rgba(17,19,23,.06);--shadow:0 14px 38px rgba(17,19,23,.09);
}
html{scroll-behavior:smooth}
body{background:
  radial-gradient(circle at 8% 0%,rgba(184,147,72,.08),transparent 28%),
  linear-gradient(180deg,#f7f8fa 0%,#f3f4f6 100%);
  min-height:100vh}
.top{
  position:sticky;top:0;z-index:50;
  background:linear-gradient(118deg,#0d0f13 0%,#171b22 56%,#24201a 100%);
  padding:15px 28px;border-bottom:1px solid rgba(212,180,110,.2);
  box-shadow:0 8px 28px rgba(0,0,0,.18)
}
.club-logo{width:64px;height:76px}
.club-logo img{filter:drop-shadow(0 8px 12px rgba(0,0,0,.28))}
.brand h1{font-size:23px;letter-spacing:.1px}
.brand p{color:#c9ced7;font-size:13px}
.user-actions{row-gap:10px}
.user-pill{background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.09);padding:7px 10px;border-radius:14px}
.badge{padding:7px 10px;font-size:11px;background:rgba(184,147,72,.08)}
.lang-select{min-height:38px}
#logoutBtn{background:rgba(255,255,255,.1);color:#fff;border:1px solid rgba(255,255,255,.11)}
#logoutBtn:hover{background:#fff;color:#111317}
.container{max-width:1580px;margin:20px auto 34px;padding:0 22px}
.nav{
  position:sticky;top:108px;z-index:35;
  background:rgba(255,255,255,.92);backdrop-filter:blur(14px);
  border:1px solid var(--line);box-shadow:var(--shadow-sm);
  padding:8px;border-radius:17px;margin-bottom:14px;
  gap:6px
}
.nav button{
  position:relative;display:inline-flex;align-items:center;gap:9px;
  padding:11px 15px;border:0;background:transparent;color:#4b5563;
  border-radius:11px;transition:.2s ease;font-size:13px
}
.nav button:before{
  width:25px;height:25px;border-radius:8px;background:#f1f3f6;
  display:inline-flex;align-items:center;justify-content:center;
  font-size:13px;font-weight:900;color:#4b5563
}
.nav button[data-view="dashboard"]:before{content:"▦"}
.nav button[data-view="assets"]:before{content:"▤"}
.nav button[data-view="add"]:before{content:"＋"}
.nav button[data-view="custodyreturn"]:before{content:"↙"}
.nav button[data-view="users"]:before{content:"♙"}
.nav button[data-view="permissions"]:before{content:"✓"}
.nav button:hover{background:#f8f5ee;color:#111317}
.nav button.active{
  background:linear-gradient(135deg,#17191e,#29251e);color:#fff;
  box-shadow:0 8px 18px rgba(17,19,23,.16)
}
.nav button.active:before{background:var(--gold);color:#fff}
.pro-pagebar{
  display:flex;justify-content:space-between;align-items:center;gap:16px;
  padding:15px 18px;margin-bottom:14px;border:1px solid var(--line);
  background:rgba(255,255,255,.78);backdrop-filter:blur(10px);
  border-radius:16px;box-shadow:var(--shadow-sm)
}
.pro-page-title{font-weight:900;font-size:18px;color:#181b20}
.pro-page-subtitle{font-size:12px;color:var(--muted);margin-top:4px}
.pro-page-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.pro-chip{font-size:11px;color:#625331;background:var(--gold-soft);border:1px solid #eadab8;border-radius:999px;padding:7px 10px;font-weight:800}
.pro-clock{font-size:11px;color:#d9dde4;white-space:nowrap;padding:7px 9px;border-radius:10px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.09)}
.view{animation:proFade .22s ease}
@keyframes proFade{from{opacity:.55;transform:translateY(3px)}to{opacity:1;transform:none}}
.stats{grid-template-columns:repeat(5,minmax(0,1fr));gap:13px}
.stat{
  position:relative;overflow:hidden;border:1px solid #e9e5dc;border-radius:18px;
  padding:18px 18px 17px;background:linear-gradient(145deg,#fff,#fdfcf9);
  box-shadow:var(--shadow-sm);min-height:120px
}
.stat:after{content:"";position:absolute;inset:auto -22px -34px auto;width:90px;height:90px;border-radius:50%;background:rgba(184,147,72,.09)}
.stat:before{
  position:absolute;left:16px;top:16px;width:36px;height:36px;border-radius:11px;
  display:flex;align-items:center;justify-content:center;background:#f2eee5;color:#8f6f30;font-weight:900
}
html[dir="ltr"] .stat:before{left:auto;right:16px}
.stat:nth-child(1):before{content:"Σ"}.stat:nth-child(2):before{content:"↗"}.stat:nth-child(3):before{content:"↙"}.stat:nth-child(4):before{content:"!"}.stat:nth-child(5):before{content:"#"}
.stat span{font-size:12px;color:#707784;font-weight:700;max-width:75%}
.stat strong{font-size:31px;color:#111317;margin-top:12px;letter-spacing:-.5px}
.grid{grid-template-columns:minmax(360px,.9fr) minmax(0,1.5fr);gap:14px}
.card{
  border:1px solid var(--line);border-radius:18px;padding:20px;
  box-shadow:var(--shadow-sm);background:rgba(255,255,255,.96)
}
.card h2{font-size:17px;padding-bottom:12px;margin-bottom:16px;border-bottom:1px solid #eef0f3}
.formgrid{gap:14px}
.field{gap:7px}
.field label,.asset-item label{color:#3f4651;font-size:12px}
.field input,.field select,.field textarea,.asset-item input,.search,.pro-select{
  border:1px solid #dfe3e8;border-radius:11px;padding:11px 12px;
  background:#fff;transition:border-color .16s,box-shadow .16s
}
.field input:focus,.field select:focus,.field textarea:focus,.asset-item input:focus,.search:focus,.pro-select:focus{
  outline:0;border-color:#b89348;box-shadow:0 0 0 3px rgba(184,147,72,.12)
}
.asset-types{border:1px solid #e7dfcf;background:linear-gradient(145deg,#fdfbf6,#fff);border-radius:15px}
.asset-types-title{color:#5c4a29}
.asset-item{background:#fff;border:1px solid #eceef1;border-radius:12px;padding:10px}
